from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    # Input shape.
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    tolerance = cell_size // 2
    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        for field in ("x", "y", "value", "quality"):
            if field not in obs or not isinstance(obs[field], int):
                return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _cell_index(obs["x"], cell_size, width, tolerance)
        row = _cell_index(obs["y"], cell_size, height, tolerance)
        if col is None or row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _render_cells(sums, counts, width, height, raw["fill_value"])
    flags = _render_flags(counts, degraded, width, height)

    total = width * height
    filled = len(counts)
    coverage = filled * 100 // total
    line = (
        "cells=" + str(total)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _cell_index(coord: int, cell_size: int, limit: int, tolerance: int) -> int | None:
    """Map a coordinate onto a cell index, snapping near the far edge, else None (dropped)."""
    index = coord // cell_size
    if 0 <= index < limit:
        return index
    if 0 <= coord < limit * cell_size + tolerance:
        return limit - 1
    return None


def _render_cells(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _render_flags(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows

